//! htmx's attributes and elements per major version (`data/htmx.data`, generated by
//! `cargo xtask web-data` from the editor data htmx ships). Embedded; only the project's
//! version is parsed, when a project uses htmx, and dropped with it.

static DATA: &str = include_str!("../data/htmx.data");

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Entry {
    pub name: &'static str,
    /// What it does (from htmx's documentation).
    pub doc: &'static str,
    /// An element (`<hx-partial>`), not an attribute.
    pub element: bool,
}

/// The entries of htmx `major` (e.g. 2 or 4).
pub fn for_version(major: u32) -> Vec<Entry> {
    DATA.lines()
        .filter(|l| !l.starts_with('#'))
        .filter_map(|line| {
            let mut f = line.split('\t');
            let (kind, majors, name, doc) =
                (f.next()?, f.next()?, f.next()?, f.next().unwrap_or(""));
            majors.split(',').any(|m| m.parse() == Ok(major)).then_some(Entry {
                name,
                doc,
                element: kind == "e",
            })
        })
        .collect()
}

/// The newest major version in the data.
pub fn newest() -> u32 {
    DATA.lines()
        .filter(|l| !l.starts_with('#'))
        .filter_map(|l| l.split('\t').nth(1))
        .flat_map(|m| m.split(','))
        .filter_map(|m| m.parse().ok())
        .max()
        .unwrap_or(2)
}

